// One-off generator: bundles master-prompt-modules.mjs + prompt-assembler.mjs
// (both ESM, for Node) into shared/prompt-assembler.js, a plain non-module
// <script> notes-factory/index.html loads directly, exposing
// window.PromptAssembler = { assembleRuntimePrompt, levelKeyFromLabel,
// parseMasterPromptModules }. Re-run any time either source file changes;
// do not hand-edit the generated file.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(__dirname, '..', '..', '..');

const modulesSrc = fs.readFileSync(path.join(__dirname, 'master-prompt-modules.mjs'), 'utf8')
  .replace(/^export /gm, '');
const assemblerSrc = fs.readFileSync(path.join(__dirname, 'prompt-assembler.mjs'), 'utf8')
  .replace(/^import .*\n/gm, '') // drop the `import { parseMasterPromptModules } from ...` line — same scope, no module system needed
  .replace(/^export /gm, '');

const out = `// AUTO-GENERATED by gen-prompt-assembler-browser.mjs from
// Automation/core/src/master-prompt-modules.mjs + prompt-assembler.mjs.
// Do not hand-edit — re-run the generator instead so this never drifts.
// Exposes window.PromptAssembler = { assembleRuntimePrompt, levelKeyFromLabel, parseMasterPromptModules }.
(function(global){
${modulesSrc}

${assemblerSrc}
global.PromptAssembler = { assembleRuntimePrompt, levelKeyFromLabel, parseMasterPromptModules, formatDiagnostic };
})(typeof window !== 'undefined' ? window : this);
`;

const outDir = path.join(REPO_ROOT, 'shared');
fs.mkdirSync(outDir, { recursive: true });
fs.writeFileSync(path.join(outDir, 'prompt-assembler.js'), out);
console.log('wrote shared/prompt-assembler.js');
